-- UK Driver Hub: new news stories (2026-10-19)
-- 3 stories, written in our own words, each with its own picture.
--
-- HOW TO ADD THEM TO THE SITE
--   1. Click inside this file in VS Code, press Ctrl+A then Ctrl+C.
--   2. In Supabase, open SQL Editor, click "+ New query", press Ctrl+V, click Run.
--   3. You should see "Success. No rows returned". The stories go live on /news
--      within 10 minutes. Edit or delete any of them in Admin -> News.
--
-- Safe to run twice: stories and pictures already on the site are skipped.
-- (The long lines of letters further down are the pictures. Don't edit them.)
--
-- Stories:
--   - Bolt moves its Standard drivers in the UK to worker status  (TaxiPoint)
--   - Edinburgh asks drivers for their views on a possible private hire car cap  (TaxiPoint)
--   - Taxis and PHVs banned from Oxford Street from 26 October  (DM News)

-- Bolt moves its Standard drivers in the UK to worker status
insert into public.news_images (key, content_type, data_base64)
values ('2026-10-12-bolt-worker-status', 'image/jpeg', '')
on conflict (key) do nothing;

insert into public.news (title, summary, takeaway, source, source_url, category, created_at, image_url)
select 'Bolt moves its Standard drivers in the UK to worker status',
  'Bolt has confirmed that drivers who work through its Standard service in the UK are moving to worker status. Worker status sits between employed and self-employed. It brings legal rights such as the National Minimum Wage and paid holiday, while drivers keep more flexibility than an employee would have.

Bolt already paid some top-ups under its Bolt Boost terms: an extra payment when earnings fall below a level based on the National Living Wage, and a holiday pay supplement of 12.07% of relevant fees. The difference now is that the legal relationship itself is changing, not just the payments.

The move follows a November 2024 Employment Tribunal ruling that the drivers who brought claims were workers while logged in to the app within their licensed area. Bolt is still challenging parts of that ruling, and law firm Leigh Day, which represents the drivers, says a hearing on compensation is due in November 2026. Bolt Flex, where drivers choose the price they accept, is a separate option, and Bolt has not said that it is changing. Uber has treated its UK drivers as workers since 2021.',
  'If you drive on Bolt Standard, read the new terms in the app. Keep your own record of hours and earnings so you can check your minimum pay and holiday pay are right. Our free Earnings and Expenses tracker can help.',
  'TaxiPoint',
  'https://www.taxi-point.co.uk/post/bolt-moves-standard-uk-drivers-to-worker-status-in-major-ride-hailing-employment-change',
  'Industry News',
  '2026-10-12 09:00:00+01'::timestamptz,
  '/news-image/2026-10-12-bolt-worker-status'
where not exists (
  select 1 from public.news
  where source_url = 'https://www.taxi-point.co.uk/post/bolt-moves-standard-uk-drivers-to-worker-status-in-major-ride-hailing-employment-change' or lower(title) = lower('Bolt moves its Standard drivers in the UK to worker status')
);

-- Edinburgh asks drivers for their views on a possible private hire car cap
insert into public.news_images (key, content_type, data_base64)
values ('2026-10-15-edinburgh-phc-survey', 'image/jpeg', '')
on conflict (key) do nothing;

insert into public.news (title, summary, takeaway, source, source_url, category, created_at, image_url)
select 'Edinburgh asks drivers for their views on a possible private hire car cap',
  'The City of Edinburgh Council has opened a public consultation on the number of private hire cars in the city. It is part of an "overprovision" assessment that will help decide whether the council should limit new private hire car licences. The consultation opened on 13 October and closes on 3 November 2026. Drivers, operators, passengers and anyone else with an interest can take part through the council''s Consultation Hub.

Edinburgh already caps the number of taxis, but there is no limit on private hire cars at the moment. The assessment follows a petition in August 2025, backed by 1,228 people and six businesses, which said there were about 1,100 active black cabs and more than 3,000 private hire cars in the city. The council''s Regulatory Committee agreed to commission the study but did not pause new licences.

The findings will go back to the Regulatory Committee. Under Scottish law, an overprovision limit would only apply to new private hire car licence applications. Drivers who already hold a licence would not automatically lose it.',
  'Edinburgh drivers, taxi or private hire: this is your chance to have a say before 3 November. Search for "Edinburgh Consultation Hub" to find the survey.',
  'TaxiPoint',
  'https://www.taxi-point.co.uk/post/edinburgh-taxi-and-private-hire-trade-handed-fresh-chance-to-influence-hotly-debated-vehicle-cap-as',
  'Local News',
  '2026-10-15 09:00:00+01'::timestamptz,
  '/news-image/2026-10-15-edinburgh-phc-survey'
where not exists (
  select 1 from public.news
  where source_url = 'https://www.taxi-point.co.uk/post/edinburgh-taxi-and-private-hire-trade-handed-fresh-chance-to-influence-hotly-debated-vehicle-cap-as' or lower(title) = lower('Edinburgh asks drivers for their views on a possible private hire car cap')
);

-- Taxis and PHVs banned from Oxford Street from 26 October
insert into public.news_images (key, content_type, data_base64)
values ('2026-10-19-oxford-street-traffic-free', 'image/jpeg', '')
on conflict (key) do nothing;

insert into public.news (title, summary, takeaway, source, source_url, category, created_at, image_url)
select 'Taxis and PHVs banned from Oxford Street from 26 October',
  'From Monday 26 October 2026, the stretch of Oxford Street in London between Orchard Street and Great Portland Street, almost a kilometre long, becomes traffic-free. Taxis, private hire vehicles, buses, cycles, scooters and pedicabs will all be kept out of that section. Emergency vehicles will still have access, and delivery and servicing vehicles can get in between midnight and 7am.

Some road changes start sooner. From 10pm on 19 October, the turns from James Street into Oxford Street and from Oxford Street into Gilbert Street close for good. Traffic from James Street will leave via Barrett Street, and Gilbert Street becomes two-way between Oxford Street and Brook Street. On the evening of Sunday 25 October, traffic will be sent away from Oxford Street between Portman Street and Winsley Street before the ban starts the next morning.

TfL is warning of diversions, closures and turning restrictions around Oxford Street, Regent Street, Bond Street and Great Portland Street. Until the ban starts, taxis and PHVs can still work the area, but pick-up and drop-off points may move. Westminster Council has raised concerns that traffic could be pushed onto smaller side roads.',
  'London drivers: from 26 October you can''t drive along Oxford Street between Orchard Street and Great Portland Street. Agree pick-up points on side streets with your passengers and allow extra time for busier roads nearby.',
  'DM News',
  'https://dmnews.co.uk/oxford-street-traffic-free-zone-to-exclude-taxis-and-private-hire-vehicles-from-26-october/',
  'Local News',
  '2026-10-19 09:00:00+01'::timestamptz,
  '/news-image/2026-10-19-oxford-street-traffic-free'
where not exists (
  select 1 from public.news
  where source_url = 'https://dmnews.co.uk/oxford-street-traffic-free-zone-to-exclude-taxis-and-private-hire-vehicles-from-26-october/' or lower(title) = lower('Taxis and PHVs banned from Oxford Street from 26 October')
);
